import math

def gcd_sum(n, k):
    # Generate the first n natural numbers
    sequence = list(range(1, n + 1))

    # Calculate the sum of GCDs of all pairs
    total_gcd_sum = 0
    for i in range(n):
        for j in range(i + 1, n):
            total_gcd_sum += math.gcd(sequence[i], sequence[j])

    # Check if the sum matches k
    if total_gcd_sum == k:
        return sequence
    else:
        return -1

# Read input
n, k = map(int, input().split())

# Get the sequence
result = gcd_sum(n, k)

# Output the result
if result == -1:
    print(-1)
else:
    print(' '.join(map(str, result)))
